import{_ as t,o,c as a,a2 as d}from"./chunks/framework.CyZTVJbV.js";const m=JSON.parse('{"title":"Search real-driver testing — 8 axis × 4 provider = 32 cell grid + real-driver env-gate (SSOT)","description":"","frontmatter":{},"headers":[],"relativePath":"concepts/search-real-driver-testing.md","filePath":"concepts/search-real-driver-testing.md"}'),r={name:"concepts/search-real-driver-testing.md"};function i(s,e,n,c,l,h){return o(),a("div",null,[...e[0]||(e[0]=[d('<h1 id="search-real-driver-testing-—-8-axis-×-4-provider-32-cell-grid-real-driver-env-gate-ssot" tabindex="-1">Search real-driver testing — 8 axis × 4 provider = 32 cell grid + real-driver env-gate (SSOT) <a class="header-anchor" href="#search-real-driver-testing-—-8-axis-×-4-provider-32-cell-grid-real-driver-env-gate-ssot" aria-label="Permalink to &quot;Search real-driver testing — 8 axis × 4 provider = 32 cell grid + real-driver env-gate (SSOT)&quot;">​</a></h1><p>kiwa&#39;s v1.13-4 search work covered the <strong>4 base axes</strong> (query mock / index mock / search mock / facet mock) as unified mocks for Meilisearch + Algolia + Typesense — the <code>docs/concepts/search-testing.md</code> doc is the SSOT for those 4 axes. v1.36 adds <strong>8 advanced axes on top of that base</strong> — the ones production search stacks hit once their mock-only Meilisearch suite is green but real Algolia sandbox rankings, real Typesense hybrid endpoints, real OpenSearch OSS synonym files, and real rolling reindex operations start showing up in customer-facing &quot;no results found&quot; post-mortems. This concept doc is the SSOT for those 8 axes; the tutorials (73-75) and dogfood app new / v2 (v1.36-2/3/4) are the concrete implementations.</p><h2 id="the-8-axis-grid" tabindex="-1">The 8-axis grid <a class="header-anchor" href="#the-8-axis-grid" aria-label="Permalink to &quot;The 8-axis grid&quot;">​</a></h2><p>The 8 advanced axes are cover-oriented — each one names a real-world failure surface every non-trivial production search stack hits within the first quarter.</p><table tabindex="0"><thead><tr><th>Axis</th><th>Real-world failure it catches</th><th>v0.3 API</th></tr></thead><tbody><tr><td>Vector</td><td>&quot;The semantic recall@10 dropped from 0.92 to 0.71 after the HNSW <code>efConstruction</code> param changed but the panel still showed green because the mock never exercised the ANN recall assertion&quot; (no state machine, no recall guard)</td><td><code>startVectorSession</code> / <code>buildVectorIndex</code> / <code>queryKnn</code> / <code>fuseHybrid</code> / <code>recallAnn</code></td></tr><tr><td>Semantic</td><td>&quot;The intent classifier tagged a support-ticket query as a product-catalog query and the cross-encoder rerank amplified the wrong result because the embedding cache leaked a stale intent tag&quot; (no intent enumeration, no rerank stability)</td><td><code>startSemanticSession</code> / <code>classifyIntent</code> / <code>understandQuery</code> / <code>cacheEmbedding</code> / <code>crossEncoderRerank</code></td></tr><tr><td>Faceted advanced</td><td>&quot;The restaurant panel showed 42 hits under Italian &gt; Pizza but the real Algolia counted 39 because the sibling Neapolitan was double-counted in the parent aggregation&quot; (no parent-child invariant, no distinct-count guard)</td><td><code>startFacetedSession</code> / <code>seedFacetedDocuments</code> / <code>computeNestedFacets</code> / <code>countDistinct</code> / <code>applyRefinedFilter</code> / <code>traverseHierarchy</code></td></tr><tr><td>Geo</td><td>&quot;The &#39;restaurants within 5 km&#39; filter returned Sapporo (900 km away) because the mock&#39;s distance was in km but the real Algolia returned meters and the client didn&#39;t check units&quot; (no unit invariant, no shape guard)</td><td><code>startGeoSession</code> / <code>seedGeoDocuments</code> / <code>filterBoundingBox</code> / <code>filterRadius</code> / <code>filterPolygon</code> / <code>resolveIsochrone</code></td></tr><tr><td>Relevance</td><td>&quot;The p95 nDCG@10 dropped from 0.83 to 0.71 after the BM25 <code>k1</code> was retuned but nobody caught it until a customer replied &#39;no results for shirt&#39;&quot; (no BM25 param flow-through, no per-query score assertion)</td><td><code>startRelevanceSession</code> / <code>seedRelevanceDocuments</code> / <code>scoreBm25</code> / <code>scoreTfIdf</code> / <code>applyCustomRanking</code> / <code>selectAbVariant</code></td></tr><tr><td>Synonym advanced</td><td>&quot;The synonym file registered <code>shirt → t-shirt</code> unidirectionally so a search for <code>t-shirt</code> missed the base document and the customer&#39;s cart abandoned&quot; (no bidirectional expansion, no phonetic / stemmer / typo safety net)</td><td><code>startSynonymSession</code> / <code>registerSynonyms</code> / <code>expandMultiLanguage</code> / <code>matchPhonetic</code> / <code>normalizeStemmer</code> / <code>bridgeTypo</code></td></tr><tr><td>Index management</td><td>&quot;The rolling reindex flipped the alias 2 seconds before the new index was fully built and 1 % of readers hit <code>index not found</code> on that window&quot; (no alias-flip atomicity, no batch-progress invariant)</td><td><code>startIndexMgmtSession</code> / <code>allocateShards</code> / <code>promoteReplica</code> / <code>advanceRollingReindex</code> / <code>swapZeroDowntime</code></td></tr><tr><td>Query DSL</td><td>&quot;The nested-query panel bucket boundary changed from 100 / 500 / 1000 to 100 / 500 / 1500 after a config rewrite and the p99 percentile line silently drifted&quot; (no bucket contract, no boolean-tree assertion)</td><td><code>startQueryDslSession</code> / <code>seedQueryDslDocuments</code> / <code>evaluateBooleanTree</code> / <code>resolveNestedQuery</code> / <code>bucketHistogram</code> / <code>computePercentile</code></td></tr></tbody></table><p>Each axis has 3 shapes — a mock-only path (fast inner loop, ms scale), a real-driver path (<code>KIWA_MODE=real</code> + real Meilisearch v1 / Typesense v27 / Algolia sandbox / OpenSearch OSS 2.x, seconds scale), and a fidelity assertion that the two produce the same output. Tutorial 73 covers the vector axis end-to-end (build → knn → hybrid → recall), tutorial 74 covers the faceted-advanced + geo axes (nested facet + distinct + bounding box + radius + polygon + isochrone), tutorial 75 covers the relevance + synonym-advanced + index-management axes (BM25 + TF-IDF + custom ranking + A/B + phonetic + stemmer + typo + rolling reindex + zero-downtime swap).</p><h2 id="the-4-provider-×-8-axis-32-cell-grid" tabindex="-1">The 4-provider × 8-axis = 32 cell grid <a class="header-anchor" href="#the-4-provider-×-8-axis-32-cell-grid" aria-label="Permalink to &quot;The 4-provider × 8-axis = 32 cell grid&quot;">​</a></h2><p>Every provider covers every axis. The mock shapes are provider-neutral (the API surface is the same across Meilisearch + Typesense + Algolia + OpenSearch OSS), the emitted event dialects are provider-specific (<code>meili.vector.index.build</code> vs <code>typesense.vector.index</code> vs <code>algolia.vector.build</code> vs <code>opensearch.knn.index.build</code>), and the fidelity harness reports the coverage explicitly.</p><table tabindex="0"><thead><tr><th>Provider</th><th>Vector</th><th>Semantic</th><th>Faceted</th><th>Geo</th><th>Relevance</th><th>Synonym</th><th>Index mgmt</th><th>Query DSL</th></tr></thead><tbody><tr><td>Meilisearch</td><td>implemented</td><td>implemented</td><td>implemented</td><td>implemented</td><td>implemented</td><td>implemented</td><td>implemented</td><td>implemented</td></tr><tr><td>Typesense</td><td>implemented</td><td>implemented</td><td>implemented</td><td>implemented</td><td>implemented</td><td>implemented</td><td>implemented</td><td>implemented</td></tr><tr><td>Algolia</td><td>implemented</td><td>implemented</td><td>implemented</td><td>implemented</td><td>implemented</td><td>implemented</td><td>implemented</td><td>implemented</td></tr><tr><td>OpenSearch OSS</td><td>implemented</td><td>implemented</td><td>implemented</td><td>implemented</td><td>implemented</td><td>implemented</td><td>implemented</td><td>implemented</td></tr></tbody></table><p>The v1.36 search grid is fully covered — every provider implements every axis because the semantics are runtime-agnostic. That is what makes cross-provider reuse (a session that runs under Meilisearch + Typesense + Algolia + OpenSearch OSS without change) even possible.</p><h3 id="why-the-search-grid-is-fully-covered" tabindex="-1">Why the search grid is fully covered <a class="header-anchor" href="#why-the-search-grid-is-fully-covered" aria-label="Permalink to &quot;Why the search grid is fully covered&quot;">​</a></h3><p>Meilisearch + Typesense + Algolia + OpenSearch OSS converged on the same neutral events at the &quot;index a document, run a query, aggregate a facet&quot; primitive — the &quot;search a term across an inverted index with an optional vector embedding&quot; shape is the same across all 4 providers, even though the wire encodings differ (JSON REST vs. gRPC-like binary vs. HTTP + Algolia batch). The <code>providerEventName(target, neutralEvent)</code> mapping table is the single point where the 4 dialects diverge; everything upstream stays neutral. The v1.36 fidelity grid at 32/32 = 100 % implemented reflects that convergence at the &quot;search primitive&quot; level.</p><h2 id="the-kiwa-mode-real-env-gate-contract" tabindex="-1">The <code>KIWA_MODE=real</code> env-gate contract <a class="header-anchor" href="#the-kiwa-mode-real-env-gate-contract" aria-label="Permalink to &quot;The `KIWA_MODE=real` env-gate contract&quot;">​</a></h2><p><code>skipUnlessReal(env)</code> returns <code>{ skip: false, reason: &#39;KIWA_MODE=real detected&#39; }</code> when <code>env.KIWA_MODE === &#39;real&#39;</code> and <code>{ skip: true, reason: &#39;KIWA_MODE!=real — skip real-driver tests (mock semantics apply)&#39; }</code> otherwise. A test that respects the contract combines the gate with a required-env presence check — the dogfood apps use this at each <code>describe.skipIf(gate.skip || envMissing.length &gt; 0)</code> block.</p><p>Per-axis env mapping.</p><ul><li><strong>Vector + Semantic dogfood</strong> → <code>KIWA_MEILI_URL</code> + <code>KIWA_TYPESENSE_URL</code> (real Meilisearch v1 + Typesense v27 reachable for hybrid + kNN query)</li><li><strong>Faceted + Geo dogfood</strong> → <code>KIWA_ALGOLIA_URL</code> + <code>ALGOLIA_KEY</code> (real Algolia sandbox reachable for nested facet + bounding box + radius + polygon queries)</li><li><strong>Relevance + Synonym + Index mgmt dogfood</strong> → <code>KIWA_OPENSEARCH_URL</code> + <code>OPENSEARCH_KEY</code> (real OpenSearch OSS 2.x testcontainer reachable for BM25 + synonym file + alias swap)</li><li><strong>Query DSL</strong> → provider-agnostic (mock-only in v1.36, no dogfood app)</li></ul><p>A test that respects the contract runs the mock path unconditionally and the real-driver path only when both <code>KIWA_MODE=real</code> and the required env are present. That means CI stays cheap by default (mock only, ms scale), the nightly job flips <code>KIWA_MODE=real</code> + the required <code>_URL</code> / <code>_KEY</code> envs, and the fidelity harness ties the two together.</p><p>Absent env means silently fall back to mock mode — the test still runs, the real-driver assertions get skipped. Absent <code>KIWA_MODE</code> means fall back to mock. An invalid <code>KIWA_MODE</code> value (anything other than <code>real</code>) also falls back to mock so a typo does not break tests.</p><h2 id="the-dogfood-app-new-v2-pattern" tabindex="-1">The dogfood app new / v2 pattern <a class="header-anchor" href="#the-dogfood-app-new-v2-pattern" aria-label="Permalink to &quot;The dogfood app new / v2 pattern&quot;">​</a></h2><p>The 3 dogfood apps (v1.36-2/3/4) each expose a <code>pnpm test</code> command that keeps the mock-only path green sub-second, and are wired for <code>pnpm test:real</code> follow-up phases when the required envs are present.</p><ul><li><code>examples/dogfood-search-vector-app</code> v2 — Meilisearch v1 + Typesense v27 stack + real hybrid + kNN + HNSW recall + docker-compose backend + <code>pnpm test:real</code> that walks the vector chain (start session → build index → kNN query → hybrid fuse → recall@k) against real Meilisearch + Typesense endpoints. 68 test.</li><li><code>examples/dogfood-search-faceted-geo-app</code> v2 — Algolia sandbox + faceted-advanced + geo bounding-box / radius / polygon / isochrone + <code>pnpm test:real</code> that walks the faceted + geo flow (nested facet → distinct count → refine → bounding box → radius) against a real Algolia sandbox. 58 test.</li><li><code>examples/dogfood-search-opensearch-app</code> new — OpenSearch OSS 2.x testcontainer + relevance-tuning + BM25 + synonym advanced + rolling reindex + <code>pnpm test:real</code> that walks the relevance + synonym + index-management flow (BM25 → synonym expand → rolling reindex → zero-downtime swap) against a real OpenSearch cluster. 73 test.</li></ul><p>The pattern each new / v2 app follows.</p><ol><li>Keep the mock-only path (<code>pnpm test</code>) green — the fast inner loop stays sub-second.</li><li>Add a <code>pnpm test:e2e</code> command that spins the docker-compose stack (Meilisearch + Typesense + Algolia mock + OpenSearch OSS, subset per app) and walks the real query flow.</li><li>Add a <code>pnpm test:real</code> command that requires the axis-specific <code>_URL</code> / <code>_KEY</code> env(s) and routes through the real provider endpoint.</li><li>Run the same fidelity-harness assertions against the real driver; failure means &quot;the mock diverged from real provider behavior&quot; — the mock gets the fix.</li><li>Emit a <code>quality-report/fidelity-latest.md</code> + <code>.json</code> that the v1.29 3-layer defensive structure (release-invariants + docs-e2e + release-smoke) picks up on merge.</li></ol><h2 id="the-not-implemented-failure-mode" tabindex="-1">The <code>not-implemented</code> failure mode <a class="header-anchor" href="#the-not-implemented-failure-mode" aria-label="Permalink to &quot;The `not-implemented` failure mode&quot;">​</a></h2><p>If the fidelity harness has a <code>planned</code> cell, the corresponding tutorial + dogfood + snippet-validation-test trio does not exist yet. The 32-cell grid at v1.36 has 0 <code>planned</code> cells — every intended cell is <code>implemented</code>. When a future milestone adds a 9th axis (e.g., <code>learned-sparse-vector</code> or <code>neural-reranker</code>), it will start as <code>planned</code> for all 4 providers, then transition to <code>implemented</code> for the ones that cover it as the milestone lands its tutorial + dogfood + snippet test.</p><h2 id="how-this-ties-into-the-13-axis-release-gate" tabindex="-1">How this ties into the 13-axis release gate <a class="header-anchor" href="#how-this-ties-into-the-13-axis-release-gate" aria-label="Permalink to &quot;How this ties into the 13-axis release gate&quot;">​</a></h2><p>v1.36 does not add a 14th release-gate axis. The 8 advanced search axes gate the search package&#39;s own tests (via <code>pnpm --filter @kiwa-lab/search test</code>) but do not surface as a per-package <code>@kiwa-lab/quality-metrics</code> axis. The reasoning — the fidelity harness is provider-shape-specific, and a package that does not export to Meilisearch / Typesense / Algolia / OpenSearch OSS has nothing to assert on. When a future milestone adds a <code>search.fidelity</code> axis that describes &quot;which search providers this package&#39;s tests hit,&quot; it will slot into the 13-axis release gate as the 14th; v1.36 keeps the axis count at 13.</p><h2 id="ssot-boundaries" tabindex="-1">SSOT boundaries <a class="header-anchor" href="#ssot-boundaries" aria-label="Permalink to &quot;SSOT boundaries&quot;">​</a></h2><ul><li>The 4 base search axes (query / index / search / facet) live in <code>docs/concepts/search-testing.md</code>. v1.36 does not modify that doc.</li><li>The 8 advanced search axes live in this doc. Tutorials 73-75 and the migration guide (v1.35 → v1.36) link back here for the axis SSOT.</li><li>The 4-provider × 8-axis grid is the harness&#39;s data structure. The <code>collectFidelityCoverage()</code> implementation in <code>packages/search/src/semantics/fidelity.ts</code> is the code SSOT — this doc&#39;s grid table is derived from that code.</li><li>The <code>KIWA_MODE=real</code> env-gate contract is shared with the v1.22 real-driver testing tutorial (auth adapters + Keycloak), the v1.31 streaming real-driver concept doc, the v1.32 database real-driver concept doc, the v1.33 payment real-driver concept doc, the v1.34 frontend real-driver concept doc, and the v1.35 observability real-driver concept doc. All six use the same <code>skipUnlessReal(env)</code> pattern; the search axes just add provider <code>_URL</code> + <code>_KEY</code> envs (<code>KIWA_MEILI_URL</code> / <code>KIWA_TYPESENSE_URL</code> / <code>KIWA_ALGOLIA_URL</code> / <code>ALGOLIA_KEY</code> / <code>KIWA_OPENSEARCH_URL</code> / <code>OPENSEARCH_KEY</code>) instead of provider-specific <code>_URL</code>-only envs.</li></ul>',29)])])}const u=t(r,[["render",i]]);export{m as __pageData,u as default};
